    'dugsiga_users',
    'dugsiga_students',
    'dugsiga_classes',
    'dugsiga_subjects',
    'dugsiga_exam_scores',
    'dugsiga_attendance',
    'dugsiga_fees',
    'dugsiga_settings',
    'dugsiga_teachers',
    'dugsiga_staff',
    'dugsiga_guardians',
    'dugsiga_staff_attendance',
    'dugsiga_timetable',
    'dugsiga_admissions',
    'dugsiga_announcements',
    'dugsiga_library_books',
    'dugsiga_library_loans',
    'dugsiga_inventory',
    'dugsiga_documents',
    'dugsiga_notifications',
    'dugsiga_fee_structures',
    'dugsiga_invoices',
    'dugsiga_payments',
    'dugsiga_expenses',
    'dugsiga_income',
    'dugsiga_budgets',
    'dugsiga_payroll',
     'dugsiga_student_audit'
  ];
BEGIN
  FOREACH tbl_name IN ARRAY tables_list LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', tbl_name);
    EXECUTE format('REVOKE ALL ON TABLE public.%I FROM anon, authenticated', tbl_name);
    EXECUTE format('GRANT ALL ON TABLE public.%I TO service_role', tbl_name);
  END LOOP;
END $dugsi$;

